//! `hick equiv` is the refactor gate: restructure a document freely, then
//! prove no generated byte moved.
//!
//! Guarantee: docs/guarantees/authoring/a-refactor-baseline-reports-drift.md

use std::process::Command;

fn hick() -> Command {
    let mut c = Command::new(env!("CARGO_BIN_EXE_hick"));
    c.env("HICKORY_EXECUTOR", "local");
    c
}

/// A document whose `out.txt` is assembled from a fragment, and one that
/// writes the same bytes literally. Same outputs, different basenames.
fn pair(dir: &std::path::Path, second_body: &str) -> (std::path::PathBuf, std::path::PathBuf) {
    let a = dir.join("a.hick");
    let b = dir.join("b.hick");
    std::fs::write(
        &a,
        "<hick:copy id=\"v\">1.0</hick:copy>\n\
         <hick:file path=\"out.txt\">v=<hick:paste select=\"#v\" /></hick:file>\n",
    )
    .unwrap();
    std::fs::write(&b, second_body).unwrap();
    (a, b)
}

fn equiv(a: &std::path::Path, b: &std::path::Path, ignore_weave: bool) -> (bool, String) {
    let mut cmd = hick();
    cmd.args(["equiv", a.to_str().unwrap(), b.to_str().unwrap()]);
    if ignore_weave {
        cmd.arg("--ignore-weave");
    }
    let out = cmd.output().unwrap();
    (
        out.status.success(),
        String::from_utf8_lossy(&out.stderr).to_string(),
    )
}

/// Every document weaves a `.md` of its own name (`bare-documents.md`), so
/// two documents at different paths differ on that file before anything they
/// GENERATE is looked at. Without a way to say so, `hick equiv` could only
/// ever compare a document with itself.
#[test]
fn two_basenames_differ_on_their_own_weaves_alone() {
    let dir = tempfile::tempdir().unwrap();
    let (a, b) = pair(
        dir.path(),
        "<hick:file path=\"out.txt\">v=1.0</hick:file>\n",
    );
    let (ok, text) = equiv(&a, &b, false);
    assert!(!ok, "{text}");
    assert!(text.contains("a.md"), "{text}");
    assert!(text.contains("b.md"), "{text}");
}

#[test]
fn ignore_weave_compares_what_the_documents_generate() {
    let dir = tempfile::tempdir().unwrap();
    let (a, b) = pair(
        dir.path(),
        "<hick:file path=\"out.txt\">v=1.0</hick:file>\n",
    );
    let (ok, text) = equiv(&a, &b, true);
    assert!(ok, "{text}");
    assert!(text.contains("equivalent:"), "{text}");
    assert!(
        text.contains("ignoring each document's own weave"),
        "the report says what it left out: {text}"
    );
}

/// The flag drops ONE file per side, not the comparison.
#[test]
fn ignore_weave_still_reports_a_real_difference() {
    let dir = tempfile::tempdir().unwrap();
    let (a, b) = pair(
        dir.path(),
        "<hick:file path=\"out.txt\">v=2.0</hick:file>\n",
    );
    let (ok, text) = equiv(&a, &b, true);
    assert!(!ok, "{text}");
    assert!(text.contains("out.txt"), "{text}");
    assert!(text.contains("NOT equivalent"), "{text}");
}
